import { type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";
import { Table, type TableColumn } from "@registry/aikoz/table/table";
import { DeltaBadge } from "@registry/aikoz/delta-badge/delta-badge";
import { BrandLogo } from "@registry/aikoz/brand-logo/brand-logo";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface LeaderboardEntry {
  /** Clé stable. Le rang ne convient pas : il change à chaque tri. */
  id: string;
  rank: number;
  /** Nom de l'établissement. Seul champ obligatoire avec `id` et `rank`. */
  name: string;
  /** Code court — `AMS`, `LYO-PDX`. Affiché en second, jamais à la place du nom. */
  code?: string;
  /** Entité de rattachement : réseau, groupe, marque. */
  organization?: string;
  /** Identifiant de marque du registre `BrandLogo`, pour la pastille. */
  brand?: string;
  /** Valeur classante, déjà formatée — le composant ne fait pas de mise en forme. */
  value: ReactNode;
  /** Écart par rapport à la période précédente, en points. */
  delta?: number;
  /**
   * Marque la ligne de l'utilisateur — l'état `Highlight` du composant Figma.
   * Une seule ligne devrait la porter.
   */
  highlighted?: boolean;
}

export interface LeaderboardProps {
  /** Ce que le classement classe, et sur quoi. **Obligatoire**, cf. `Table`. */
  caption: string;
  captionHidden?: boolean;
  entries: LeaderboardEntry[];
  /** Intitulé de la colonne de valeur. */
  valueLabel?: string;
  /** Libellé de la ligne mise en avant, pour l'annonce. */
  highlightLabel?: string;
  loading?: boolean;
  empty?: ReactNode;
  density?: "compact" | "default";
  className?: string;
}

// Or, argent, bronze. Ces trois teintes ne viennent PAS des tokens et n'y
// viendront pas : ce sont des références culturelles à des métaux, pas des
// couleurs d'interface. Elles ne suivent ni le thème ni le registre, comme
// les couleurs de marque.
const MEDAILLES: Record<number, { fond: string; encre: string; nom: string }> = {
  1: { fond: "#C9A227", encre: "#241A00", nom: "1re place" },
  2: { fond: "#9DA3A8", encre: "#15181A", nom: "2e place" },
  3: { fond: "#A9713B", encre: "#1B0F04", nom: "3e place" },
};

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Classement d'établissements.
 *
 * **Bâti sur `Table`, et pas sur une liste de `<div>`.** Un classement porte
 * plusieurs attributs comparables par ligne — rang, nom, réseau, valeur,
 * écart — c'est la définition d'un tableau. En mode tableau, un lecteur
 * d'écran annonce alors « Amsterdam-Schiphol, taux de réponse, 94 % » à
 * chaque déplacement, ce qu'une pile de div ne donne jamais.
 *
 * **Il n'y a pas de composant `RankRow` exporté**, contrairement au fichier
 * Figma. Une ligne qui n'a de sens qu'à l'intérieur de son tableau n'est pas
 * un composant : c'est un rendu de cellule. L'exporter inviterait à la poser
 * ailleurs, où elle perdrait ses en-têtes — donc son sens. Même raisonnement
 * que l'absence de `CardTitle` dans `Card`.
 *
 * **Le podium ne tient pas à la couleur.** Le composant Figma n'expose que
 * `Default` et `Highlight` ; l'or, l'argent et le bronze sont produits ici à
 * partir de la spec. Ils sont donc doublés : la pastille métallique porte le
 * CHIFFRE du rang, et son nom complet est dit en `sr-only`. Un utilisateur
 * qui ne distingue pas l'or du bronze lit « 1re place » — et de toute façon
 * le rang est écrit.
 *
 * La ligne « vous » se signale par un trait latéral et un libellé annoncé,
 * jamais par la seule teinte du fond : mesuré ailleurs dans ce système, un
 * voile de surlignage ne dépasse pas 1,19:1.
 */
export function Leaderboard({
  caption,
  captionHidden = false,
  entries,
  valueLabel = "Valeur",
  highlightLabel = "Votre établissement",
  loading,
  empty,
  density = "default",
  className,
}: LeaderboardProps) {
  const avecMarque = entries.some((e) => e.brand);
  const avecDelta = entries.some((e) => e.delta !== undefined);

  const columns: TableColumn<LeaderboardEntry>[] = [
    {
      key: "rank",
      header: "Rang",
      width: "4.5rem",
      cell: (e) => {
        const m = MEDAILLES[e.rank];
        return (
          <span className="inline-flex items-center gap-2">
            <span
              className={cn(
                "inline-flex size-6 shrink-0 items-center justify-center rounded-full",
                "text-2xs font-semibold tabular-nums",
                !m && "bg-[var(--muted)] text-muted-foreground"
              )}
              style={m ? { backgroundColor: m.fond, color: m.encre } : undefined}
            >
              {e.rank}
            </span>
            {m && <span className="sr-only">{m.nom}</span>}
          </span>
        );
      },
    },
    {
      key: "name",
      header: "Établissement",
      cell: (e) => (
        <span className="flex items-center gap-2.5 min-w-0">
          {avecMarque && e.brand && <BrandLogo brand={e.brand} size="sm" decorative />}
          <span className="flex flex-col min-w-0">
            <span className="truncate font-medium text-foreground">
              {/* Une seule chaîne : un `sr-only` séparé produisait
                  « Marseille Prado — Votre établissement » avec une espace
                  surnuméraire avant le tiret. */}
              {e.highlighted ? (
                <>
                  <span className="sr-only">{`${e.name} — ${highlightLabel}`}</span>
                  <span aria-hidden="true">{e.name}</span>
                </>
              ) : (
                e.name
              )}
              {e.highlighted && (
                <>
                  {/* Marqueur invisible : il ne sert qu'au sélecteur CSS du
                      trait latéral. L'annonce passe par le sr-only ci-dessus,
                      pas par lui. */}
                  <span data-vous hidden />
                </>
              )}
            </span>
            {(e.code || e.organization) && (
              // Le code et le réseau sont en retrait mais RESTENT du texte :
              // ils passent 4,5:1, ce ne sont pas des mentions décoratives.
              <span className="truncate text-xs text-muted-foreground">
                {[e.code, e.organization].filter(Boolean).join(" · ")}
              </span>
            )}
          </span>
        </span>
      ),
    },
    { key: "value", header: valueLabel, numeric: true, cell: (e) => e.value },
  ];

  if (avecDelta) {
    columns.push({
      key: "delta",
      header: "Évolution",
      numeric: true,
      width: "7rem",
      cell: (e) =>
        e.delta === undefined ? (
          // Une cellule vide se lit « vide », ce qui est juste : la donnée
          // manque. Un tiret se lirait « tiret », ce qui n'est pas la même
          // information.
          <span className="sr-only">Non renseigné</span>
        ) : (
          <DeltaBadge value={e.delta} size="sm" />
        ),
    });
  }

  return (
    <Table
      caption={caption}
      captionHidden={captionHidden}
      columns={columns}
      rows={entries}
      getRowKey={(e) => e.id}
      rowHeaderKey="name"
      loading={loading}
      empty={empty}
      density={density}
      className={cn(
        // Le trait latéral de la ligne « vous ». En `box-shadow` intérieur
        // plutôt qu'en bordure : la bordure décalerait les cellules.
        "[&_tr:has([data-vous])]:shadow-[inset_3px_0_0_0_var(--ring)]",
        "[&_tr:has([data-vous])]:bg-[var(--surface-hover)]",
        className
      )}
    />
  );
}

import { type ReactNode } from "react";
import { cn } from "@registry/aikoz/lib/utils";
import { Skeleton } from "@registry/aikoz/skeleton/skeleton";

// ─── Types ────────────────────────────────────────────────────────────────────

export type SortDirection = "asc" | "desc";

export interface TableSort {
  key: string;
  direction: SortDirection;
}

export interface TableColumn<T> {
  key: string;
  /** En-tête de colonne. Court : il est relu à chaque cellule par un
   *  lecteur d'écran en mode tableau. */
  header: string;
  /** Rendu de la cellule. Par défaut, la valeur brute de `row[key]`. */
  cell?: (row: T) => ReactNode;
  /**
   * Colonne de nombres : alignée à droite et en chiffres tabulaires, pour
   * que les unités s'empilent et que la comparaison verticale soit possible.
   */
  numeric?: boolean;
  /** Rend l'en-tête cliquable et pose `aria-sort`. */
  sortable?: boolean;
  /** Largeur CSS imposée — `"12rem"`, `"25%"`. */
  width?: string;
}

export interface TableProps<T> {
  /**
   * Ce que le tableau contient — **obligatoire**. C'est son nom accessible,
   * et c'est ce qui permet de savoir dans quel tableau on est quand une page
   * en porte plusieurs. Rendu en `<caption>`, donc lié nativement, sans
   * `aria-label` à maintenir en double.
   */
  caption: string;
  /** Masque la légende visuellement. Elle reste lue. */
  captionHidden?: boolean;
  columns: TableColumn<T>[];
  rows: T[];
  getRowKey: (row: T, index: number) => string;
  /**
   * Colonne qui NOMME la ligne — le libellé d'agence, le nom d'aéroport.
   * Elle est rendue en `<th scope="row">`, ce qui fait annoncer « Amsterdam,
   * taux de réponse, 94 % » au lieu de « 94 % » tout court quand on navigue
   * de cellule en cellule.
   */
  rowHeaderKey?: string;
  sort?: TableSort;
  onSortChange?: (sort: TableSort) => void;
  /** Affiche des lignes d'attente à la place des données. */
  loading?: boolean;
  /** Nombre de lignes d'attente. */
  loadingRows?: number;
  /** Rendu quand `rows` est vide — un `EmptyState`, en général. */
  empty?: ReactNode;
  density?: "compact" | "default";
  className?: string;
}

// ─── Sous-éléments ────────────────────────────────────────────────────────────

/** Deux chevrons superposés : l'actif est plein, l'autre effacé. La direction
 *  ne tient donc pas à la seule couleur — la FORME diffère. */
function Fleche({ direction }: { direction?: SortDirection }) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 10 12"
      className="size-2.5 shrink-0"
      fill="currentColor"
    >
      <path d="M5 0.5 8 4H2z" opacity={direction === "asc" ? 1 : 0.3} />
      <path d="M5 11.5 2 8h6z" opacity={direction === "desc" ? 1 : 0.3} />
    </svg>
  );
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Tableau de données.
 *
 * Un vrai `<table>`, pas une grille CSS de `div`. Ce n'est pas une question
 * de goût : les balises de tableau portent des RELATIONS que rien ne remplace.
 * Un lecteur d'écran en mode tableau annonce, à chaque déplacement, l'en-tête
 * de colonne et l'en-tête de ligne de la cellule où il arrive — « Amsterdam,
 * taux de réponse, 94 % ». Une grille de `div` ne donne que « 94 % », et
 * l'utilisateur doit compter les colonnes de tête.
 *
 * Trois choses que ce composant fait et qu'on oublie presque toujours :
 *
 * 1. **`<caption>` plutôt qu'`aria-label`.** La légende est visible par
 *    défaut, liée nativement, et ne peut pas se désynchroniser d'un titre
 *    voisin. `captionHidden` la masque quand la mise en page l'exige.
 * 2. **Le conteneur qui défile est focusable.** Un tableau plus large que son
 *    cadre défile horizontalement ; sans `tabIndex={0}` sur le conteneur, la
 *    partie hors champ est inatteignable au clavier — on ne peut pas faire
 *    défiler ce sur quoi on ne peut pas se poser. Il porte `role="region"` et
 *    un nom, sinon ce nouvel arrêt de tabulation serait muet.
 * 3. **Le tri s'annonce par `aria-sort` sur le `<th>`**, pas par une icône.
 *    Le bouton reste dans l'en-tête plutôt que d'être l'en-tête lui-même :
 *    un `<th>` cliquable sans bouton n'est ni focusable ni actionnable au
 *    clavier.
 */
export function Table<T>({
  caption,
  captionHidden = false,
  columns,
  rows,
  getRowKey,
  rowHeaderKey,
  sort,
  onSortChange,
  loading = false,
  loadingRows = 5,
  empty,
  density = "default",
  className,
}: TableProps<T>) {
  const cellule = density === "compact" ? "px-3 py-2" : "px-4 py-3";

  function trier(key: string) {
    const direction: SortDirection =
      sort?.key === key && sort.direction === "asc" ? "desc" : "asc";
    onSortChange?.({ key, direction });
  }

  const vide = !loading && rows.length === 0;

  return (
    <div
      // `role="region"` + nom + `tabIndex` : les trois vont ensemble. Sans le
      // nom, un lecteur d'écran annonce « région » sans dire laquelle ; sans
      // `tabIndex`, le débordement horizontal est inatteignable au clavier.
      role="region"
      aria-label={caption}
      tabIndex={0}
      // `aria-busy` porté UNE fois par le conteneur, pas par chaque squelette :
      // c'est le tableau qui charge, pas quatorze rectangles.
      aria-busy={loading || undefined}
      className={cn(
        // `min-w-0` avec `overflow-x-auto`, toujours : un élément de flex ou de
        // grille vaut `min-width: auto` et ne rétrécit pas sous son contenu. Sans
        // lui, le conteneur s'élargit au lieu de défiler, et c'est la PAGE qui
        // finit par défiler à sa place.
        "w-full min-w-0 overflow-x-auto rounded-[var(--radius)] border border-border bg-card",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
        className
      )}
    >
      <table className="w-full border-collapse text-sm">
        <caption
          className={cn(
            "text-left text-sm text-muted-foreground",
            captionHidden ? "sr-only" : cellule
          )}
        >
          {caption}
        </caption>

        <thead>
          <tr className="border-b border-border">
            {columns.map((c) => {
              const actif = sort?.key === c.key;
              return (
                <th
                  key={c.key}
                  scope="col"
                  // `aria-sort` ne va que sur la colonne triée : le poser à
                  // « none » partout ferait annoncer « non trié » sur chaque
                  // en-tête, à chaque parcours.
                  aria-sort={
                    actif
                      ? sort.direction === "asc"
                        ? "ascending"
                        : "descending"
                      : undefined
                  }
                  style={c.width ? { width: c.width } : undefined}
                  className={cn(
                    cellule,
                    "font-semibold text-foreground",
                    c.numeric ? "text-right" : "text-left"
                  )}
                >
                  {c.sortable && onSortChange ? (
                    <button
                      type="button"
                      onClick={() => trier(c.key)}
                      className={cn(
                        "inline-flex items-center gap-1.5 min-h-6 rounded-[calc(var(--radius)/2)]",
                        "font-semibold hover:text-[var(--secondary)]",
                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
                        c.numeric && "flex-row-reverse"
                      )}
                    >
                      {c.header}
                      <Fleche direction={actif ? sort.direction : undefined} />
                    </button>
                  ) : (
                    c.header
                  )}
                </th>
              );
            })}
          </tr>
        </thead>

        <tbody>
          {loading &&
            Array.from({ length: loadingRows }, (_, i) => (
              <tr key={`attente-${i}`} className="border-b border-border last:border-0">
                {columns.map((c) => (
                  <td key={c.key} className={cellule}>
                    <Skeleton shape="text" className={c.numeric ? "w-12 ml-auto" : "w-4/5"} />
                  </td>
                ))}
              </tr>
            ))}

          {vide && (
            <tr>
              {/* `colSpan` sur toute la largeur : une cellule vide par colonne
                  ferait annoncer autant de cellules vides. */}
              <td colSpan={columns.length} className="p-0">
                {empty}
              </td>
            </tr>
          )}

          {!loading &&
            rows.map((row, i) => (
              <tr
                key={getRowKey(row, i)}
                className="border-b border-border last:border-0 hover:bg-[var(--surface-hover)]"
              >
                {columns.map((c) => {
                  const contenu = c.cell
                    ? c.cell(row)
                    : ((row as Record<string, unknown>)[c.key] as ReactNode);
                  const classes = cn(
                    cellule,
                    // Chiffres tabulaires : sans eux, les colonnes de nombres
                    // ne s'alignent pas verticalement et la comparaison d'une
                    // ligne à l'autre demande de relire chiffre par chiffre.
                    c.numeric ? "text-right tabular-nums" : "text-left"
                  );
                  return c.key === rowHeaderKey ? (
                    <th
                      key={c.key}
                      scope="row"
                      className={cn(classes, "font-medium text-foreground")}
                    >
                      {contenu}
                    </th>
                  ) : (
                    <td key={c.key} className={cn(classes, "text-foreground")}>
                      {contenu}
                    </td>
                  );
                })}
              </tr>
            ))}
        </tbody>
      </table>
    </div>
  );
}

import { type HTMLAttributes } from "react";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface SkeletonProps extends HTMLAttributes<HTMLDivElement> {
  /** Forme du bloc. `text` prend la hauteur d'une ligne, `circle` un rond. */
  shape?: "block" | "text" | "circle";
}

// ─── Composant ────────────────────────────────────────────────────────────────

/**
 * Bloc d'attente.
 *
 * **Il est intégralement invisible aux technologies d'assistance**, et ce
 * n'est pas un oubli : annoncer « rectangle gris » quatorze fois ne renseigne
 * personne. C'est au CONTENEUR de dire qu'un chargement est en cours, une
 * fois, par `aria-busy="true"` — et de dire ce qui a chargé une fois fini,
 * par une région live. Un squelette qui parle est un squelette qui bavarde.
 *
 * L'animation est coupée par `motion-reduce` : une pulsation permanente sur
 * toute une page déclenche des malaises chez les personnes sensibles au
 * mouvement (WCAG 2.3.3). Sans elle le bloc reste parfaitement lisible — il
 * n'a jamais porté d'information dans son mouvement.
 *
 * `--track` et non `--muted` : en thème sombre ce dernier vaut exactement
 * `--card`, le squelette y serait strictement invisible. C'est le même piège
 * que la piste de `ProgressBar`.
 */
export function Skeleton({ shape = "block", className, ...props }: SkeletonProps) {
  return (
    <div
      aria-hidden="true"
      className={cn(
        "bg-[var(--track)] motion-safe:animate-pulse",
        shape === "circle" && "rounded-full aspect-square",
        shape === "text" && "h-4 rounded-[calc(var(--radius)/2)]",
        shape === "block" && "rounded-[var(--radius)]",
        className
      )}
      {...props}
    />
  );
}

export interface SkeletonTextProps {
  /** Nombre de lignes. */
  lines?: number;
  className?: string;
}

/**
 * Paragraphe d'attente. La dernière ligne est plus courte — un bloc de
 * lignes toutes égales ne ressemble à aucun texte réel, et l'œil met plus
 * longtemps à comprendre qu'il regarde une attente.
 */
export function SkeletonText({ lines = 3, className }: SkeletonTextProps) {
  return (
    <div className={cn("flex flex-col gap-2", className)}>
      {Array.from({ length: lines }, (_, i) => (
        <Skeleton key={i} shape="text" className={i === lines - 1 ? "w-3/5" : "w-full"} />
      ))}
    </div>
  );
}

import { ArrowUpward, ArrowDownward, Remove } from "@material-symbols-svg/react/rounded";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@registry/aikoz/lib/utils";

// ─── Variants ────────────────────────────────────────────────────────────────

const badgeVariants = cva(
  [
    "inline-flex items-center gap-0.5 shrink-0",
    "rounded-full font-semibold whitespace-nowrap tabular-nums",
  ],
  {
    variants: {
      tone: {
        // PLUS DE BORDURE, et un voile deux fois plus dense (16 % au lieu de 8).
        //
        // Le contour était justifié par WCAG 1.4.11, « 3:1 conteneur/fond ».
        // Relu, le critère ne s'applique pas ici : il vise les COMPOSANTS
        // d'interface — ce qui permet d'identifier un contrôle et son état —
        // et les objets graphiques nécessaires à la compréhension. Une pastille
        // de variation n'est ni l'un ni l'autre : elle n'est pas interactive,
        // et son sens est entièrement porté par sa flèche et son texte, qui
        // tiennent 4,5:1. La pastille elle-même n'ajoute aucune information.
        //
        // Tenir un seuil là où il ne s'applique pas n'est pas de la prudence,
        // c'est du bruit : deux traits par carte que rien n'exige. Le voile
        // densifié suffit à faire lire la forme.
        //
        // Le texte descend de 0,03 en clarté pour compenser le voile plus
        // sombre — mesuré sur le pire fond, la ligne mise en avant d'un
        // classement.
        positive: [
          "text-[var(--success)]",
          "bg-[color-mix(in_oklch,var(--success),transparent_84%)]",
        ],
        negative: [
          "text-[var(--destructive-text)]",
          "bg-[color-mix(in_oklch,var(--destructive-text),transparent_84%)]",
        ],
        // `--neutral-text`, pas `--muted-foreground` : ce dernier est le gris du
        // texte SECONDAIRE, emprunté faute de rôle. Une variation stable est
        // une donnée, au même titre qu'une hausse ou une baisse — elle mérite
        // son rôle, et il est désormais bleu ardoise plutôt que gris.
        neutral: [
          "text-[var(--neutral-text)]",
          "bg-[color-mix(in_oklch,var(--neutral-text),transparent_84%)]",
        ],
      },
      size: {
        sm: "text-2xs px-1.5 py-0.5",
        md: "text-xs px-2 py-0.5",
      },
    },
    defaultVariants: { tone: "neutral", size: "md" },
  }
);

const iconSize = { sm: "w-2.5 h-2.5", md: "w-3 h-3" } as const;

// ─── Types ────────────────────────────────────────────────────────────────────

export type DeltaTone = "positive" | "negative" | "neutral";

export interface DeltaBadgeProps
  extends Omit<VariantProps<typeof badgeVariants>, "tone"> {
  /** Variation à afficher. Le signe détermine le ton, sauf si `tone` est forcé. */
  value: number;
  /** Unité accolée à la valeur : `%`, ` pts`, etc. */
  unit?: string;
  /**
   * Force le ton. Utile quand « moins » est un progrès — un délai de réponse
   * qui baisse est une bonne nouvelle et doit rester vert.
   */
  tone?: DeltaTone;
  /** En deçà de ce seuil (valeur absolue), la variation est jugée neutre. */
  neutralThreshold?: number;
  /**
   * Libellé accessible. Par défaut « en hausse de 12 % ».
   * `null` si un parent annonce déjà la variation — le badge devient alors
   * décoratif, comme `ScoreStars` et `ProgressBar`. Sans ça, un badge posé
   * dans une carte cliquable reste un élément annonçable orphelin.
   */
  label?: string | null;
  className?: string;
}

// ─── Composant ────────────────────────────────────────────────────────────────

const ICON = {
  positive: ArrowUpward,
  negative: ArrowDownward,
  neutral: Remove,
} as const;

/**
 * Étiquette de variation.
 *
 * Extrait de `kpi-card.tsx`, où il vivait inliné sous le nom `TrendBadge` et
 * ne gérait que positif / négatif. L'état neutre — prévu par la spec de Louis
 * et par le composant Figma `Tag` — est ajouté ici.
 *
 * L'information n'est jamais portée par la seule couleur : une flèche haut /
 * bas / tiret double le ton, et `aria-label` donne le sens en toutes lettres.
 */
export function DeltaBadge({
  value,
  unit = "%",
  tone,
  size = "md",
  neutralThreshold = 0,
  label,
  className,
}: DeltaBadgeProps) {
  const resolved: DeltaTone =
    tone ??
    (Math.abs(value) <= neutralThreshold
      ? "neutral"
      : value > 0
      ? "positive"
      : value < 0
      ? "negative"
      : "neutral");

  const Icon = ICON[resolved];
  const magnitude = Math.abs(value).toLocaleString("fr-FR", {
    maximumFractionDigits: 1,
  });
  const signed = `${value > 0 ? "+" : value < 0 ? "−" : ""}${magnitude}${unit}`;

  const decorative = label === null;
  const accessibleLabel = decorative
    ? undefined
    : label ??
      (resolved === "neutral"
        ? `stable, ${magnitude}${unit}`
        : resolved === "positive"
        ? `en hausse de ${magnitude}${unit}`
        : `en baisse de ${magnitude}${unit}`);

  return (
    <span
      className={cn(badgeVariants({ tone: resolved, size }), className)}
      aria-label={accessibleLabel}
      role={decorative ? undefined : "img"}
      aria-hidden={decorative ? true : undefined}
    >
      <Icon className={iconSize[size ?? "md"]} aria-hidden="true" />
      <span aria-hidden="true">{signed}</span>
    </span>
  );
}

